 static Process Client(string script,int port,string role){var node=Environment.GetEnvironmentVariable("SKY_AUTHORITY_NODE");if(string.IsNullOrEmpty(node)||!File.Exists(node))throw new Exception("Node executable required");var info=new ProcessStartInfo(node,"\""+script+"\" "+port+" "+role){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,RedirectStandardOutput=true,RedirectStandardError=true};return Process.Start(info);}
